222	[[nodiscard]] std::string trim_copy(std::string_view s) {
223	    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.front())) != 0) s.remove_prefix(1);
224	    while (!s.empty() && std::isspace(static_cast<unsigned char>(s.back())) != 0) s.remove_suffix(1);
225	    return std::string{s};
226	}
