253	[[nodiscard]] double parse_min_free_gb_from_env() {
254	    std::string const s = env_trimmed("COMDARE_MIN_FREE_GB");
255	    if (s.empty()) return 0.0;
256	
257	    errno      = 0;
258	    char*  end = nullptr;
259	    double v   = std::strtod(s.c_str(), &end);
260	    if (end == s.c_str() || *end != '\0' || errno == ERANGE || v < 0.0) {
261	        // Fail-loud statt 0.0: ein Tippfehler ("4,5"/"4gb") wuerde sonst die RAM-Admission
262	        // still deaktivieren (B3-Klasse) -- der Abbruch landet im try/catch des E4-Blocks.
263	        throw std::runtime_error("COMDARE_MIN_FREE_GB ungueltig: '" + s + "'");
264	    }
265	    return v;
266	}
