268	[[nodiscard]] std::optional<std::size_t> parse_size_env_strict(char const* name) {
269	    std::string const s = env_trimmed(name);
270	    if (s.empty()) return std::nullopt;
271	
272	    std::uint64_t value  = 0;
273	    auto const [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value, 10);
274	    if (ec != std::errc{} || ptr != s.data() + s.size() ||
275	        value > static_cast<std::uint64_t>((std::numeric_limits<std::size_t>::max)())) {
276	        throw std::runtime_error(std::string{name} + " ungueltig: '" + s + "'");
277	    }
278	    return static_cast<std::size_t>(value);
279	}
